{"plan_json": "{
  "objectives": [
    {
      "id": 1,
      "objective": "Search for literature on flowability metrics that predict LPBF powder spreadability (Hall flow, Hausner ratio, angle of repose, GranuDrum, FT4, shear cell) with correlation strengths",
      "rationale": "Core question 1 - need to identify which flowability tests best predict spread-layer quality in LPBF",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 2,
      "objective": "Search for literature on aluminium alloy powder (AlSi10Mg, AlSi12) flowability characterization for LPBF, including granular Bond number effects",
      "rationale": "AlSi powders have low density increasing cohesion-to-weight ratio - need specific data",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 3,
      "objective": "Search for literature on screw/auger feeder behavior correlated with flowability metrics (feed factor, volumetric fill, RSD, speed dependence, tilt dependence)",
      "rationale": "Core question 2 - need evidence linking auger performance to standard flowability measures",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 4,
      "objective": "Search for rotating-drum flowability indices definitions (dynamic angle, cohesive index, avalanche statistics) and analogies to feeder mass-discharge fluctuations",
      "rationale": "Core question 3 - need to establish whether feeder fluctuations can proxy for rotating drum metrics",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 5,
      "objective": "Search for magnitude of flowability metric changes that correspond to practical spreadability differences in gas-atomized powders, and batch-to-batch variation drivers",
      "rationale": "Core question 4 - need quantitative thresholds and sensitivity to powder attributes",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 6,
      "objective": "Search for recommended test conditions for reproducible powder flowability screening (conditioning, humidity, replicates, pitfalls)",
      "rationale": "Core question 5 - practical guidance for test protocol",
      "status": "pending",
      "result": null,
      "evaluation": null
    },
    {
      "id": 7,
      "objective": "Gather and synthesize all evidence, create summary artifacts, and provide final answer with recommendation",
      "rationale": "Final synthesis and recommendation of two scalar flowability numbers from tilting auger + balance",
      "status": "pending",
      "result": null,
      "evaluation": null
    }
  ]
}"}

